mapper.select:
select a.* from 

        iot_data_${entity.uid} a


        iot_collect_data a




        and a.cid=#{entity.cid}


        and a.device_sn=#{entity.deviceSn}


        and a.product_code=#{entity.productCode}


        and a.field_id=#{entity.fieldId}


        and a.task_id=#{entity.taskId}


        and a.status=#{entity.status}


        and a.grade is not null and a.grade != ''


order by a.collect_time desc


    select count(1) calc_value, field, category


    select avg(CAST(collect_value AS double)) calc_value, field, category


    select max(CAST(collect_value AS double)) calc_value, field, category


    select min(CAST(collect_value AS double)) calc_value, field, category

from (
    select collect_value, field

        ,TO_CHAR(collect_time, 'yyyy') category


        ,TO_CHAR(collect_time, 'yyyy-mm') category


        ,TO_CHAR(collect_time, 'yyyy-mm-dd') category


        ,TO_CHAR(collect_time, 'yyyy-mm-dd hh24') category

    from


            iot_data_${uid}


            iot_collect_data




            and product_code=#{productCode}


            and (
            field = #{field}
        )

        and cast(collect_time as bigint) between #{startTimestamp} and #{endTimestamp}

) b
group by category,field

select * from


        iot_data_${uid}


        iot_collect_data




        and product_code=#{productCode}


        and (
        field = #{field}
    )

    and cast(collect_time as bigint) between #{startTimestamp} and #{endTimestamp}

select * from


        iot_data_${uid}


        iot_collect_data




        and product_code=#{productCode}


        and (
        field = #{field}
    )

    and cast(collect_time as bigint) between #{startTimestamp} and #{endTimestamp}

select uid,cid from (
    select distinct uid, cid, collect_time from


        iot_data_${entity.uid}


        iot_collect_data




            and device_sn=#{entity.deviceSn}


            and collect_mode = #{entity.collectMode}


            and product_code=#{entity.productCode}


            and device_group_id=#{entity.deviceGroupId}


            and task_id=#{entity.taskId}



                and cast(collect_time as bigint) between #{entity.startTimestamp} and #{entity.endTimestamp}


                and cast(collect_time as bigint) >= #{entity.startTimestamp}


                and #{entity.endTimestamp} >= cast(collect_time as bigint)



)
order by collect_time desc

SELECT MAX(CAST(collect_value AS DOUBLE)) AS `max`, MIN(CAST(collect_value AS DOUBLE)) AS `min`,
       AVG(CAST(collect_value AS DOUBLE)) AS `avg`, COUNT(*) AS `count`,
       (SELECT collect_time
        FROM iot_data_${uid}
        WHERE collect_time BETWEEN #{start} AND #{end}
          AND collect_value IS NOT NULL AND field_id = #{fieldId} AND collect_status = 1
        ORDER BY CAST(collect_value AS DOUBLE) DESC LIMIT 1) AS `maxTime`,
       (SELECT collect_time
        FROM iot_data_${uid}
        WHERE collect_time BETWEEN #{start} AND #{end}
          AND collect_value IS NOT NULL AND field_id = #{fieldId} AND collect_status = 1
        ORDER BY CAST(collect_value AS DOUBLE) LIMIT 1) AS `minTime`
FROM iot_collect_data
WHERE uid = #{uid}
  AND field_id = #{fieldId} AND collect_time BETWEEN #{start} AND #{end}
  AND collect_value IS NOT NULL AND collect_status = 1

SELECT uid, field, field_id, collect_value, collect_time, collect_status, device_group_id
FROM iot_data_${uid}
WHERE field_id = #{fieldId}
  AND collect_value IS NOT NULL AND collect_status = 1
  AND collect_time BETWEEN #{start} AND #{end}
ORDER BY collect_time

SELECT uid, field, field_name, field_id, collect_value, collect_time, collect_status, device_group_id, grade, indicator
FROM iot_data_${uid}
WHERE collect_time = #{collectTime} AND field_id != #{excludeFieldId}
  AND collect_value IS NOT NULL AND collect_status = 1 AND grade IS NOT NULL

SELECT a.uid, a.field, a.field_name, a.field_id, a.collect_value, a.collect_time, a.grade, a.indicator
     , a.collect_status, a.device_name, a.device_group_id
FROM iot_collect_data a
WHERE a.field_id = #{fieldId}
  AND a.collect_time = TO_UNIXTIMESTAMP('${collectTime}') AND a.uid != #{excludeUid}
  AND a.collect_value IS NOT NULL AND a.collect_status = 1 AND a.grade IS NOT NULL

SELECT uid, field, field_id, field_name, collect_value, collect_time, grade, indicator,
       device_name, device_sn, device_group_id, puid, cid, collect_status
FROM iot_data_${uid}
WHERE field_id = #{fieldId} AND collect_time = #{collectTime}
  AND collect_value IS NOT NULL AND collect_status = 1
LIMIT 1

SELECT uid, field, field_id, field_name, collect_value, collect_time, grade, indicator, device_name, device_sn, device_group_id, puid, cid, collect_status FROM ( SELECT uid, field, field_id, field_name, collect_value, collect_time, grade, indicator, device_name, device_sn, device_group_id, puid, cid, collect_status, ROW_NUMBER() OVER ( PARTITION BY uid, field_id ORDER BY CASE grade WHEN 'fatal' THEN 0 WHEN 'urgent' THEN 1 WHEN 'warn' THEN 2 WHEN 'notice' THEN 3 WHEN 'normal' THEN 4 WHEN 'status' THEN 5 WHEN 'indicator' THEN 6 ELSE 99 END ) AS rn FROM iot_collect_data WHERE cid = #{cid} AND collect_status = 1 AND collect_value IS NOT NULL AND uid != #{excludeUid} AND field_id != #{excludeFieldId}
AND grade = #{grade}
AND grade IS NOT NULL
) t WHERE rn = 1 ORDER BY CASE grade WHEN 'fatal' THEN 0 WHEN 'urgent' THEN 1 WHEN 'warn' THEN 2 WHEN 'notice' THEN 3 WHEN 'normal' THEN 4 WHEN 'status' THEN 5 WHEN 'indicator' THEN 6 ELSE 99 END LIMIT 500

SELECT uid, field, field_id, field_name, collect_value, collect_time, grade, indicator,
       device_name, device_sn, device_group_id, puid, cid, collect_status
FROM (
    SELECT uid, field, field_id, field_name, collect_value, collect_time, grade, indicator,
           device_name, device_sn, device_group_id, puid, cid, collect_status,
           ROW_NUMBER() OVER (
               PARTITION BY uid, field_id
               ORDER BY CASE grade WHEN 'fatal' THEN 0 WHEN 'urgent' THEN 1
                        WHEN 'warn' THEN 2 WHEN 'notice' THEN 3
                        WHEN 'normal' THEN 4 WHEN 'status' THEN 5
                        WHEN 'indicator' THEN 6 ELSE 99 END
           ) AS rn
    FROM iot_collect_data
    WHERE collect_time BETWEEN #{startTime} AND #{endTime}
      AND collect_status = 1 AND collect_value IS NOT NULL
      AND uid != #{excludeUid} AND field_id != #{excludeFieldId}
      AND (

                puid = #{puid} OR device_group_id = #{deviceGroupId}


                puid = #{puid}


                device_group_id = #{deviceGroupId}

          )


            AND grade = #{grade}


            AND grade IS NOT NULL


) t WHERE rn = 1
ORDER BY CASE grade WHEN 'fatal' THEN 0 WHEN 'urgent' THEN 1
         WHEN 'warn' THEN 2 WHEN 'notice' THEN 3
         WHEN 'normal' THEN 4 WHEN 'status' THEN 5
         WHEN 'indicator' THEN 6 ELSE 99 END
LIMIT 500
